/**
 * THE HARNESS SIDE OF THE KILL MATRIX (blueprint row 86): starts the Core as a process
 * (`core-child.ts`), drives a session through its routes, kills processes with SIGKILL, starts
 * the next Core, and reads what is left - rows as `dems_owner`, files, the manifest, operation 41.
 *
 * NEVER A REAL DEVICE: the selector of the throw-away database must name the four built-in FAKE
 * devices; the sources are generated by the private development helper. Loopback only; the
 * worker listens on the Core's two ingest ports 127.0.0.1:8554 and 8556.
 */
import { type ChildProcess, execFileSync, fork } from 'node:child_process';
import { createHash } from 'node:crypto';
import { appendFileSync, copyFileSync, existsSync, mkdirSync, openSync, readFileSync, readSync, closeSync, readdirSync, statSync } from 'node:fs';
import { resolve } from 'node:path';
import { parseManifestV2 } from '@dems/shared/evidence-package';
import type { Pool } from 'pg';
import type { ChildCommand, ChildInit, ChildView } from './core-child';
import type { KillPoint } from './cells';
import type { FolderView, FragmentRow, JobRow, ManifestView, VerifyView } from './judge';

export const REPOSITORY = resolve(import.meta.dirname, '../../../../../..');
const CORE_SERVER = resolve(REPOSITORY, 'apps/core-server');
export const WORKER = resolve(REPOSITORY, 'apps/capture-worker/build/capture-worker');
export const HELPER = resolve(REPOSITORY, '.data/helpers/ffmpeg');
const CHILD = resolve(import.meta.dirname, 'core-child.ts');
const FAKE_DEVICES = ['CAM-01', 'CAM-02', 'MIC-01', 'MIC-02'];

export const sleep = (ms: number): Promise<void> => new Promise((done) => setTimeout(done, ms));

export async function until<Value>(what: string, limitMs: number, read: () => Promise<Value | null> | Value | null, diagnose: () => unknown = () => null): Promise<Value> {
  for (const started = Date.now(); Date.now() - started < limitMs; ) {
    const value = await read();
    if (value !== null) return value;
    await sleep(250);
  }
  throw new Error(`not reached within ${limitMs} ms: ${what} ${JSON.stringify(await diagnose())}`);
}

export interface Rig {
  readonly database: ChildInit['database'];
  readonly dataDir: string;
  readonly mediaStoreDir: string;
  /** `dems_owner` on the throw-away database: fixtures and assertions only. */
  readonly owner: Pool;
}

export interface Exit {
  readonly code: number | null;
  readonly signal: NodeJS.Signals | null;
}

/** A command without its serial number (distributed over the union). */
export type Command = ChildCommand extends infer One ? (One extends { id: number } ? Omit<One, 'id'> : never) : never;

export interface CoreProcess {
  readonly pid: number;
  readonly exited: Promise<Exit>;
  /** Null while the process lives. */
  exit(): Exit | null;
  call<Value>(command: Command): Promise<Value>;
  view(sessionId: string | null): Promise<ChildView>;
  /** True when a capture worker is among the Core's descendants. */
  workerRuns(): Promise<boolean>;
  /** SIGKILL from the harness to every descendant (capture worker first, then the helpers) and to the Core. Resolves when the Core's process is gone. */
  crash(): Promise<{ readonly killed: readonly string[] }>;
  /** The graceful end of a Core that is no subject of a kill any more. */
  close(): Promise<void>;
}

const alive = new Set<ChildProcess>();
/** Every Core this file started and that still lives is killed: no process outlives a run. */
export function killLeftCores(): void {
  for (const child of alive) {
    for (const pid of descendantsOf(child.pid ?? -1)) signal(pid);
    child.kill('SIGKILL');
  }
  alive.clear();
}

function descendantsOf(pid: number): number[] {
  let direct: number[] = [];
  try {
    direct = execFileSync('/usr/bin/pgrep', ['-P', String(pid)], { encoding: 'utf8' }).trim().split('\n').filter((line) => line !== '').map(Number);
  } catch {
    // pgrep exits 1 when the process has no child.
  }
  return [...direct, ...direct.flatMap((child) => descendantsOf(child))];
}

const commandOf = (pid: number): string => {
  try {
    return execFileSync('/bin/ps', ['-o', 'comm=', '-p', String(pid)], { encoding: 'utf8' }).trim().split('/').pop() ?? '';
  } catch {
    return '';
  }
};

/** SIGKILL to every process whose arguments name the rig's throw-away data directory (the worker's log path, a helper's pipe). Returns their names. */
export function sweep(rig: Rig): string[] {
  let pids: number[] = [];
  try {
    pids = execFileSync('/usr/bin/pgrep', ['-f', rig.dataDir], { encoding: 'utf8' }).trim().split('\n').filter((line) => line !== '').map(Number);
  } catch {
    // None.
  }
  return pids.filter((pid) => pid !== process.pid).map((pid) => {
    const name = commandOf(pid);
    signal(pid);
    return name;
  });
}

/** True once the worker has created the recording of VIDEO-01 (its init segment): the P1 moment, before any fragment is durable. */
export const recordingStarted = (rig: Rig, sessionId: string): boolean => existsSync(recordingOf(rig, sessionId, 'VIDEO-01')) && statSync(recordingOf(rig, sessionId, 'VIDEO-01')).size > 0;

function signal(pid: number): void {
  try {
    process.kill(pid, 'SIGKILL');
  } catch {
    // Already gone.
  }
}

/** One boot of the Core on the rig's database, data directory and media root. Rejects when the Core does not come up. */
export async function startCore(rig: Rig, arm: KillPoint | null): Promise<CoreProcess> {
  // The environment of the child names no credential: the database configuration goes over the IPC channel.
  const env: Record<string, string> = {};
  for (const name of ['PATH', 'HOME', 'TMPDIR', 'LANG', 'TZ']) if (process.env[name] !== undefined) env[name] = process.env[name] as string;
  const child = fork(CHILD, [], { cwd: CORE_SERVER, env, execArgv: ['--import', 'tsx'], stdio: ['ignore', 'ignore', 'pipe', 'ipc'] });
  alive.add(child);
  let stderr = '';
  child.stderr?.on('data', (chunk: Buffer) => {
    stderr = (stderr + chunk.toString('utf8')).slice(-2_000);
  });
  let exit: Exit | null = null;
  const exited = new Promise<Exit>((done) => {
    child.once('exit', (code, sig) => {
      exit = { code, signal: sig };
      alive.delete(child);
      done(exit);
    });
  });
  let serial = 0;
  const waiting = new Map<number, { resolve: (value: unknown) => void; reject: (error: Error) => void }>();
  void exited.then((end) => {
    for (const entry of waiting.values()) entry.reject(new Error(`the Core's process ended (${end.signal ?? end.code}) before it answered`));
    waiting.clear();
  });
  const ready = new Promise<void>((done, fail) => {
    child.on('message', (message: { type?: string; id?: number; ok?: boolean; value?: unknown; error?: string }) => {
      if (message.type === 'ready') return done();
      if (message.type === 'failed') return fail(new Error(`the Core did not start: ${message.error}`));
      const entry = message.id === undefined ? undefined : waiting.get(message.id);
      if (entry === undefined || message.id === undefined) return;
      waiting.delete(message.id);
      if (message.ok === true) entry.resolve(message.value);
      else entry.reject(new Error(message.error ?? 'the command failed'));
    });
    void exited.then((end) => fail(new Error(`the Core's process ended (${end.signal ?? end.code}) before it was ready: ${stderr.slice(-600)}`)));
  });
  child.send({ type: 'init', database: rig.database, dataDir: rig.dataDir, mediaStoreDir: rig.mediaStoreDir, worker: WORKER, helper: HELPER, arm } satisfies ChildInit);
  // A Core armed inside RECOVERY may die before it says it is ready: that is the cell, not a failed boot.
  await ready.catch((error: unknown) => {
    if (arm !== null && exit !== null && (exit as Exit).signal === 'SIGKILL') return;
    throw error;
  });

  const call = <Value>(command: Command): Promise<Value> =>
    new Promise<Value>((done, fail) => {
      if (exit !== null) return fail(new Error("the Core's process has ended"));
      serial += 1;
      waiting.set(serial, { resolve: done as (value: unknown) => void, reject: fail });
      child.send({ ...command, id: serial });
    });
  return {
    pid: child.pid ?? -1,
    exited,
    exit: () => exit,
    call,
    view: (sessionId) => call<ChildView>({ op: 'view', sessionId }),
    workerRuns: async () => descendantsOf(child.pid ?? -1).some((pid) => commandOf(pid) === 'capture-worker'),
    async crash() {
      const descendants = descendantsOf(child.pid ?? -1).map((pid) => ({ pid, name: commandOf(pid) }));
      // The worker first (its files are left as they are), then the Core before its supervisor can act on the exit, then the helpers.
      const workers = descendants.filter((entry) => entry.name === 'capture-worker');
      for (const entry of workers) signal(entry.pid);
      child.kill('SIGKILL');
      for (const entry of descendants) signal(entry.pid);
      await exited;
      // A process the Core started between the listing and its death (a worker being spawned) names the rig's data directory in its arguments.
      const late = sweep(rig);
      return { killed: [...workers.map(() => 'capture-worker'), 'core', ...descendants.filter((entry) => entry.name !== 'capture-worker').map((entry) => entry.name), ...late.map((name) => `${name} (started during the kill)`)] };
    },
    async close() {
      if (exit !== null) return;
      await call({ op: 'close' }).catch(() => {});
      await Promise.race([exited, sleep(10_000)]);
      if (exit === null) {
        for (const pid of descendantsOf(child.pid ?? -1)) signal(pid);
        child.kill('SIGKILL');
        await exited;
      }
    },
  };
}

export interface Operator {
  readonly cookie: string;
  readonly investigatorId: string;
}

export const signIn = (core: CoreProcess): Promise<Operator> => core.call<Operator>({ op: 'signIn' });
export const post = (core: CoreProcess, operator: Operator, url: string, payload?: Record<string, unknown>): Promise<{ statusCode: number; body: string }> => core.call({ op: 'inject', method: 'POST', url, cookie: operator.cookie, ...(payload === undefined ? {} : { payload }) });

/** From nothing to RECORDING through the routes. Resolves with the session ID the moment the second start is answered: nothing is durable yet. */
export async function startRecording(core: CoreProcess, operator: Operator): Promise<string> {
  const before = await core.view(null);
  if (!before.mounted) throw new Error('the sealing host is not mounted: the Core is not in a real capture mode');
  if (JSON.stringify(before.assigned) !== JSON.stringify(FAKE_DEVICES.map((id) => [id, 'FAKE']))) throw new Error(`the selector does not name the four FAKE devices only: ${JSON.stringify(before.assigned)}`);
  await core.call({ op: 'tabletLink' });
  const created = await post(core, operator, '/api/v1/session', { caseNumber: 'LP/2026/1009-0086', subjectType: 'SAKSI', subjectName: 'Generated Subject', investigatorId: operator.investigatorId, room: 'Interview Room 1', profileId: 'STANDARD_1080P25' });
  if (![200, 201].includes(created.statusCode)) throw new Error(`create answered ${created.statusCode}: ${created.body.slice(0, 300)}`);
  const sessionId = (await core.view(null)).session?.id ?? '';
  const armed = await post(core, operator, `/api/v1/session/${sessionId}/start`);
  if (armed.statusCode !== 202) throw new Error(`the first start answered ${armed.statusCode}: ${armed.body.slice(0, 300)}`);
  await until('the pre-check ends', 20_000, async () => {
    const session = (await core.view(null)).session;
    return session?.state === 'ARMED' || (session?.state === 'PRECHECK' && session.precheckDone) ? true : null;
  });
  if ((await core.view(null)).session?.state === 'PRECHECK') {
    const acknowledged = await post(core, operator, `/api/v1/session/${sessionId}/precheck/acknowledge`);
    if (acknowledged.statusCode !== 200) throw new Error(`the acknowledgement answered ${acknowledged.statusCode}`);
  }
  const started = await post(core, operator, `/api/v1/session/${sessionId}/start`);
  if (started.statusCode !== 200) throw new Error(`the start answered ${started.statusCode}: ${started.body.slice(0, 300)}`);
  return sessionId;
}

export async function untilDurable(core: CoreProcess): Promise<void> {
  await until('the first durable fragment', 40_000, async () => {
    const session = (await core.view(null)).session;
    if (session?.state !== 'RECORDING') throw new Error(`the session left RECORDING: ${session?.state}`);
    return session.captureDurable === true ? true : null;
  }, async () => (await core.view(null)).codes);
}

// ---- what is left: rows, files, the manifest ----

export const jobRows = async (rig: Rig, sessionId: string): Promise<JobRow[]> =>
  (await rig.owner.query<JobRow>('SELECT step, status, attempt, checkpoint FROM public.sealing_jobs WHERE session_id = $1 ORDER BY started_at, step', [sessionId])).rows;

export const fragmentRows = async (rig: Rig, sessionId: string): Promise<(FragmentRow & { byteOffset: number; byteLength: number })[]> =>
  (await rig.owner.query<{ track_id: string; seq: number; sha256: string; byte_offset: string; byte_length: string }>('SELECT track_id, seq, sha256, byte_offset, byte_length FROM public.recording_fragments WHERE session_id = $1 ORDER BY track_id, seq', [sessionId])).rows.map((row) => ({
    trackId: row.track_id,
    seq: row.seq,
    sha256: row.sha256,
    byteOffset: Number(row.byte_offset),
    byteLength: Number(row.byte_length),
  }));

export const countOf = async (rig: Rig, sql: string, values: readonly unknown[]): Promise<number> => Number((await rig.owner.query<{ n: string }>(sql, [...values])).rows[0]?.n ?? 'NaN');

export const sessionRow = async (rig: Rig): Promise<string[]> => (await rig.owner.query<{ state: string }>('SELECT state FROM public.active_session')).rows.map((row) => row.state);

export const packageDirOf = (rig: Rig, sessionId: string): string => `${rig.mediaStoreDir}/SESSION-${sessionId}`;

export function folderOf(rig: Rig, sessionId: string): FolderView | null {
  const dir = packageDirOf(rig, sessionId);
  if (!existsSync(dir)) return null;
  return { top: readdirSync(dir), fragments: existsSync(`${dir}/fragments`) ? readdirSync(`${dir}/fragments`) : null };
}

/** Names under the staging folder of the session that a finished seal must not leave half-written. */
export function stagingLeft(rig: Rig, sessionId: string): string[] {
  const dir = `${rig.mediaStoreDir}/.sealing/${sessionId}`;
  if (!existsSync(dir)) return [];
  return (readdirSync(dir, { recursive: true }) as string[]).filter((name) => name.endsWith('.part'));
}

export function manifestOf(rig: Rig, sessionId: string): ManifestView & { readonly evidenceId: string; readonly developmentSources: boolean; readonly truncated: readonly string[] } {
  const manifest = parseManifestV2(JSON.parse(readFileSync(`${packageDirOf(rig, sessionId)}/session-manifest.json`, 'utf8')));
  return {
    evidenceId: manifest.evidenceId,
    developmentSources: manifest.developmentSources,
    interrupted: manifest.timeline.interrupted,
    tracks: manifest.tracks.map((track) => ({ trackId: track.trackId, bytes: track.bytes, sha256Plain: track.sha256Plain ?? '', fragmentCount: track.fragmentCount ?? -1 })),
    files: manifest.files.map((file) => ({ trackId: file.trackId, fragments: file.fragments.map((fragment) => ({ seq: fragment.seq, sha256Plain: fragment.sha256Plain ?? '', interrupted: fragment.interrupted })) })),
    truncated: manifest.files.flatMap((file) => file.fragments.filter((fragment) => (fragment as { truncated?: boolean }).truncated === true).map((fragment) => `${file.trackId}:${fragment.seq}`)),
  };
}

/** The bytes of the manifest and of the signature as they are on the disk now, or null when one is not there. */
export function signedBytesOf(rig: Rig, sessionId: string): { readonly manifest: string; readonly signature: string } | null {
  const dir = packageDirOf(rig, sessionId);
  if (!existsSync(`${dir}/session-manifest.json`) || !existsSync(`${dir}/signature.sig`)) return null;
  return { manifest: readFileSync(`${dir}/session-manifest.json`).toString('base64'), signature: readFileSync(`${dir}/signature.sig`).toString('base64') };
}

const TRACKS = ['VIDEO-01', 'VIDEO-02'];
const recordingOf = (rig: Rig, sessionId: string, trackId: string): string => `${packageDirOf(rig, sessionId)}/${trackId}.mp4`;

/** A copy of the two plaintext RECORDINGS as a dead process left them, outside the media root. Null when they are gone (removed by a finished commit). */
export function copyRecordings(rig: Rig, sessionId: string): Record<string, string> | null {
  if (!TRACKS.every((trackId) => existsSync(recordingOf(rig, sessionId, trackId)))) return null;
  const dir = `${rig.dataDir}/kill-matrix-reference`;
  mkdirSync(dir, { recursive: true });
  return Object.fromEntries(
    TRACKS.map((trackId) => {
      copyFileSync(recordingOf(rig, sessionId, trackId), `${dir}/${trackId}.mp4`);
      return [trackId, `${dir}/${trackId}.mp4`];
    }),
  );
}

/** SHA-256 of the first `bytes` bytes of each copied recording: what `tracks[].sha256Plain` of a seal of that prefix must be. */
export function prefixDigests(copies: Record<string, string>, manifest: ManifestView): Record<string, string> {
  return Object.fromEntries(
    manifest.tracks.map((track) => {
      const hash = createHash('sha256');
      const file = openSync(copies[track.trackId] as string, 'r');
      try {
        const buffer = Buffer.alloc(1 << 20);
        for (let at = 0; at < track.bytes; ) {
          const read = readSync(file, buffer, 0, Math.min(buffer.length, track.bytes - at), at);
          if (read === 0) break;
          hash.update(buffer.subarray(0, read));
          at += read;
        }
      } finally {
        closeSync(file);
      }
      return [track.trackId, hash.digest('hex')];
    }),
  );
}

/**
 * THE TORN TAIL OF P2, SYNTHETIC. A real SIGKILL never tore a fragment in row 59's runs (note 21:
 * 0 of 100), so the size-mismatch tail of test strategy §F.1 is staged: the first half of the
 * last recorded fragment of VIDEO-01 is appended to the dead worker's file - a `moof` that
 * declares more bytes than follow. Returns the number of bytes appended.
 */
export function appendTornTail(rig: Rig, sessionId: string, rows: readonly { trackId: string; byteOffset: number; byteLength: number }[]): number {
  const last = rows.filter((row) => row.trackId === 'VIDEO-01').at(-1);
  if (last === undefined) throw new Error('no recorded fragment of VIDEO-01 to tear');
  const path = recordingOf(rig, sessionId, 'VIDEO-01');
  const half = Math.floor(last.byteLength / 2);
  const file = openSync(path, 'r');
  const torn = Buffer.alloc(half);
  try {
    readSync(file, torn, 0, half, last.byteOffset);
  } finally {
    closeSync(file);
  }
  appendFileSync(path, torn);
  return half;
}


export async function verify(core: CoreProcess, operator: Operator, evidenceId: string): Promise<VerifyView & { readonly failures: readonly string[] }> {
  const answer = await post(core, operator, `/api/v1/evidence/${evidenceId}/verify`);
  let body: { ok?: unknown; overall?: unknown; interrupted?: unknown; checks?: { id: string; status: string; findings?: { code?: string; trackId?: string; seq?: number }[] }[] } = {};
  try {
    body = JSON.parse(answer.body);
  } catch {
    // Not JSON: the status code says it.
  }
  return { statusCode: answer.statusCode, ok: body.ok, overall: body.overall, interrupted: body.interrupted, checks: (body.checks ?? []).map((check) => ({ id: check.id, status: check.status })),
    // What a failed check names: codes and positions, no value.
    failures: (body.checks ?? []).filter((check) => check.status === 'FAIL').flatMap((check) => (check.findings ?? []).slice(0, 6).map((finding) => `${check.id} ${finding.code ?? '?'}${finding.trackId === undefined ? '' : ` ${finding.trackId}`}${finding.seq === undefined ? '' : `:${finding.seq}`}`)),
  };
}
